  'ambPortal.rules.title': 'Rules & account',
  'ambPortal.rules.earnTitle': 'How rewards work',
  'ambPortal.rules.earn1': 'Bounty: {bounty} for each store you bring in, once it’s set up — an owner account, at least one worker and a posted schedule — and FruitCrew has approved it.',
  'ambPortal.rules.earn2': 'Payment shares: {rate} of each successful payment after the free month ({perMonth} a month at today’s price), for up to {months} paid months per store.',
  'ambPortal.rules.earn3': 'A business’s other locations earn {extra} of their payments. A yearly plan counts as 12 paid months at once.',
  'ambPortal.rules.earn4': 'Shares wait out the {days}-day refund window. Refunded or disputed payments are taken back, even after a payout.',
  'ambPortal.rules.earn5': 'Failed payments, free months and canceled stores earn nothing. Starting a plan again doesn’t restart the paid months.',
  'ambPortal.rules.noGuarantee': 'Earnings depend on businesses signing up and staying. Nothing here is guaranteed income.',
  'ambPortal.rules.claimTitle': 'Claiming businesses',
  'ambPortal.rules.yourCall': 'It’s up to you whether, when and how you reach out — there are no hours, schedules or quotas.',
  'ambPortal.rules.claim1': 'Claiming a business is how you get credit for it and keep other ambassadors from approaching the same place. Logging your visits keeps the claim yours.',
  'ambPortal.rules.claim2': 'You can hold {n} businesses at a time. A claim lapses {days} days after your last logged outreach.',
  'ambPortal.rules.claim3': 'Please don’t approach a business someone else has claimed, an existing customer, or one marked do-not-contact.',
  'ambPortal.rules.claim4': 'Once a business has been contacted, trying again needs FruitCrew’s OK — ask from the business’s page.',
  'ambPortal.rules.guideTitle': 'Tips for approaching businesses',
  'ambPortal.rules.guide1': 'Visit when it’s quiet — mid-morning or mid-afternoon, not the lunch rush.',
  'ambPortal.rules.guide2': 'Ask for the owner or manager. If they’re busy, leave your info and come back.',
  'ambPortal.rules.guide3': 'Be honest about what FruitCrew does and costs. Don’t promise discounts or features.',
  'ambPortal.rules.guide4': 'Never pressure anyone. A polite “no” is fine — log it and move on.',
  'ambPortal.rules.guide5': 'If they ask not to be contacted, record “Don’t contact us” and stop.',
  'ambPortal.rules.guide6': 'Don’t refer a business you own, work for, or are closely related to.',
  'ambPortal.rules.guide7': 'Posting about FruitCrew online? Say that you earn a referral reward — for example “#ad”.',
  'ambPortal.rules.termsTitle': 'Program terms',
  'ambPortal.rules.accepted': 'You accepted version {v} on {date}.',
  'ambPortal.rules.notAccepted': 'You haven’t accepted the current terms yet.',
  'ambPortal.rules.readTerms': 'Read the terms (version {v})',
  'ambPortal.rules.hideTerms': 'Hide the terms',
  'ambPortal.rules.accountTitle': 'Account',
  'ambPortal.rules.signedInAs': 'Signed in as {email}',
  'ambPublic.signIn': 'Sign in',
  'ambPublic.kicker': 'Student Ambassador Program',
  'ambPublic.title': 'Help local businesses run smoother — and earn while you do',
  'ambPublic.lead': 'Introduce cafés, shops and restaurants near you to FruitCrew. Work when it suits you, around your classes.',
  'ambPublic.whatTitle': 'What’s FruitCrew?',
  'ambPublic.what': 'Scheduling for small teams: a manager builds the week in minutes, workers see and trade their shifts on their phones, and payroll hours add up on their own.',
  'ambPublic.howTitle': 'How it works',
  'ambPublic.how1': 'Apply below. FruitCrew reviews every application.',
  'ambPublic.how2': 'Once approved, you get a login, your own referral link and a QR code.',
  'ambPublic.how3': 'Claim local businesses in the app so nobody visits the same place twice, then introduce FruitCrew.',
  'ambPublic.how4': 'When a business signs up through you and gets going, you earn — and keep earning while it pays.',
  'ambPublic.earnTitle': 'What you can earn',
  'ambPublic.bounty': 'when a store you bring in gets set up',
