  'help.subtitle': 'A short guide for owners and managers.',
  'help.setup.summary': 'Six steps to your first schedule',
  'help.week.summary': 'What happens each week, and when',
  'help.edit.summary': 'Add, move and offer shifts',
  'help.requests.summary': 'Swaps, pickups and time off',
  'help.team.summary': 'Profiles, levels and sign-ups',
  'help.payroll.summary': 'Hours, overtime, pay and export',
  'help.clock.summary': 'Clocking in, timesheets and POS hours',
  'help.settings.summary': 'Stores, shift needs and managers',
  'help.chat.summary': 'Messages and the shift handoff',
  'help.open': 'Open {page} ›',
  'help.contact': 'Still stuck? We’re happy to help:',
  'help.week.title': 'Your weekly routine',
  'help.week.1': 'Friday — everyone gets a reminder to check their availability for next week.',
  'help.week.2': 'Saturday — FruitCrew drafts next week from everyone’s availability and your shift needs. Home tells you when it’s ready.',
  'help.week.3': 'You — open Schedule, look over the draft, fix anything, and tap Post schedule. Your team is notified. This week stays live until Sunday’s over: ‹ takes you back to change it, and the crew can still swap their shifts.',
  'help.week.4': 'Change these days and times for each store in Settings › Reminders & auto-draft.',
  'help.edit.title': 'Changing the schedule',
  'help.edit.1': 'Tap anyone on the board to change their shifts, or + Add shift to put anyone on any day. Days shows the week day by day; People shows a row per person with their hours. If a day is understaffed, the top of the page says how many people short you are.',
  'help.edit.2': 'Changed a week that’s already posted? Tap Repost schedule so your team sees the update.',
  'help.edit.3': 'Use ‹ and › to move between weeks. Plan next week starts the next one while this week stays posted.',
  'help.edit.4': 'Short-handed, or someone can\'t make it? Tap the gap (or their shift) and choose Offer it to the crew — it goes in everyone\'s Market for whoever\'s free to pick up. ⋯ also has Copy last week and Post without notifying anyone.',
  'help.requests.title': 'Requests',
  'help.requests.1': 'Workers give away, swap, and pick up shifts in their Market. Anything that needs your OK lands in Requests — approve or deny it there.',
  'help.requests.2': 'Time off shows up there too. The scheduler already keeps people off their days off; Got it lets them know you saw it, and Turn down tells them (with your reason) that they can still be scheduled.',
  'help.team.title': 'Your team',
  'help.team.1': 'Tap anyone on Team to see everything about them: stores and level, hour limits, day rules, fixed shifts, availability, time off, and hours worked.',
  'help.team.2': 'Levels go New, Regular, Senior, Manager. New workers are only scheduled on time windows that ask for a New person, so they’re never left on their own.',
  'help.team.3': 'People who join with your store’s sign-up link wait on Team until you approve them.',
  'help.payroll.title': 'Payroll',
  'help.payroll.1': 'Payroll adds up everyone’s hours for a pay period, or any dates you pick, with overtime (past 40 hours in a week) apart, and estimated pay once you set pay rates on Team — Export CSV hands it to your payroll service. Choose weekly, every two weeks, or monthly in Settings › Company.',
  'help.clock.title': 'Time clock',
  'help.clock.1': 'Off unless you turn it on, per store, in Settings › Time clock. Pick FruitCrew and everyone clocks in, out and on breaks from My Shifts; Home shows who’s in and who isn’t yet. Pick your POS (Toast, Square…) and you import its time entries instead.',
  'help.clock.2': 'Timesheets (in Payroll) put each day’s hours next to the schedule and point out late starts, missing clock-outs and hours nobody scheduled. Fix or add an entry, then approve the week — Payroll uses hours worked for that store.',
  'help.settings.title': 'Settings',
  'help.settings.1': 'Company — your business name, pay cycle, and whether managers can see pay.',
  'help.settings.2': 'Locations — each store’s shift needs, hours & holidays, responsibilities, sign-up link, and reminder timing.',
  'help.settings.3': 'Managers & owners — invite others to help run the schedule.',
  'help.chat.title': 'Chat & Notes',
  'help.chat.1': 'Chat is for store-wide and direct messages. Notes are the shift handoff — refunds, complaints, lost & found — and stay open until someone resolves them.',
