  'help.open': '打开{page} ›',
  'help.contact': '还有问题？我们很乐意帮忙：',
  'help.week.title': '每周流程',
  'help.week.1': '周五 — 每个人都会收到提醒，确认下周的可上班时间。',
  'help.week.2': '周六 — FruitCrew 根据大家的可上班时间和你的排班需求，自动起草下周班表。准备好后首页会提示你。',
  'help.week.3': '你 — 打开“排班”，检查草稿，调整需要改的地方，然后点 发布班表。团队会收到通知。本周在周日结束前都还在进行中：点「‹」可以回去修改，员工也还能换班。',
  'help.week.4': '可在 设置 › 提醒与自动排班 中为每家门店更改这些日期和时间。',
  'help.edit.title': '修改班表',
  'help.edit.1': '点排班板上的任何人即可修改他们的班次，点「+ 添加班次」可以在任意一天给任何人排班。「按天」逐天显示这一周；「按人」每人一行，并显示工时。如果某天人手不足，页面顶部会显示还差几个人。',
  'help.edit.2': '修改了已发布的一周？点 重新发布，团队就能看到更新。',
  'help.edit.3': '用 ‹ 和 › 切换周次。“排下一周”会开始下一周，同时本周保持已发布状态。',
  'help.edit.4': '人手不够，或有人来不了？点空缺（或那个人的班），选「开放给大家来抢」— 它会出现在大家的「换班」里，有空的人都能抢。「⋯」里还有「复制上周」和「发布，但不通知任何人」。',
  'help.requests.title': '申请',
  'help.requests.1': '员工在“换班”里转让、交换和认领班次。需要你批准的都会出现在“申请”里 — 在那里批准或拒绝。',
  'help.requests.2': '请假也会显示在那里。排班系统本来就会避开员工的请假日；点「知道了」让他们知道你已看到，点「不批准」会告诉他们（附上你的原因）这几天仍可能被排班。',
  'help.team.title': '你的团队',
  'help.team.1': '在“团队”页点任何人，即可查看其全部信息：门店和级别、工时上限、日期规则、固定班次、可上班时间、请假和已工作时长。',
  'help.team.2': '级别依次为 新人、普通、资深、经理。新人只会被排到需要新人的时段，确保他们不会单独上班。',
  'help.team.3': '通过门店注册链接加入的人，会在“团队”页等待你批准。',
  'help.payroll.title': '薪资工时',
  'help.payroll.1': '薪资工时页会汇总每个人在一个发薪周期（或你选的任意日期）内的工时，并单列加班（一周超过 40 小时）；在「团队」里设了时薪后还会显示预估工资 — 点「导出 CSV」交给你的薪资服务。可在 设置 › 公司 中选择每周、每两周或每月。',
  'help.clock.title': '打卡',
  'help.clock.1': '默认关闭，可在 设置 › 打卡 中按门店开启。选 FruitCrew，大家在「我的班次」里上下班打卡和休息，首页会显示谁已到岗、谁还没到。选收银系统（Toast、Square 等），则改为导入它的打卡记录。',
  'help.clock.2': '工时表（在「薪资工时」里）把每天的实际工时和排班放在一起，标出迟到、未下班打卡和排班外的工时。修改或补录记录后批准本周 — 薪资工时会按这家店的实际工作时间计算。',
  'help.settings.title': '设置',
  'help.settings.1': '公司 — 公司名称、发薪周期，以及经理能否看到工资。',
  'help.settings.2': '门店 — 每家门店的排班需求、营业时间与节假日、职责、注册链接和提醒时间。',
  'help.settings.3': '经理与老板 — 邀请其他人一起管理排班。',
  'help.chat.title': '聊天与备注',
  'help.chat.1': '聊天用于门店群聊和私信。备注用于交接班 — 退款、投诉、失物招领 — 在有人处理之前会一直保留。',
