  'ambPortal.rules.earn1': 'Bono: {bounty} por cada tienda que traigas, una vez en marcha (cuenta de dueño, al menos un trabajador y un horario publicado) y aprobada por FruitCrew.',
  'ambPortal.rules.earn2': 'Comisiones: el {rate} de cada pago exitoso después del mes gratis ({perMonth} al mes al precio actual), hasta {months} meses pagados por tienda.',
  'ambPortal.rules.earn3': 'Las otras sucursales de un negocio dan el {extra} de sus pagos. Un plan anual cuenta como 12 meses pagados de una vez.',
  'ambPortal.rules.earn4': 'Las comisiones esperan los {days} días de reembolso. Los pagos reembolsados o disputados se descuentan, incluso después de pagarte.',
  'ambPortal.rules.earn5': 'Los pagos fallidos, los meses gratis y las tiendas canceladas no generan nada. Volver a empezar un plan no reinicia los meses pagados.',
  'ambPortal.rules.noGuarantee': 'Las ganancias dependen de que los negocios se registren y se queden. Nada de esto es un ingreso garantizado.',
  'ambPortal.rules.claimTitle': 'Reservar negocios',
  'ambPortal.rules.yourCall': 'Tú decides si, cuándo y cómo contactar: no hay horas, horarios ni cuotas.',
  'ambPortal.rules.claim1': 'Reservar un negocio es cómo obtienes el crédito y evitas que otros embajadores vayan al mismo lugar. Registrar tus visitas mantiene la reserva.',
  'ambPortal.rules.claim2': 'Puedes tener {n} negocios a la vez. Una reserva vence {days} días después de tu último contacto registrado.',
  'ambPortal.rules.claim3': 'Por favor no te acerques a un negocio reservado por otro, a un cliente o a uno marcado como no contactar.',
  'ambPortal.rules.claim4': 'Si un negocio ya fue contactado, volver a intentarlo requiere el visto bueno de FruitCrew; pídelo desde su página.',
  'ambPortal.rules.guideTitle': 'Consejos para acercarte a los negocios',
  'ambPortal.rules.guide1': 'Visita cuando haya calma: media mañana o media tarde, no en la hora de la comida.',
  'ambPortal.rules.guide2': 'Pregunta por el dueño o encargado. Si están ocupados, deja tu información y vuelve.',
  'ambPortal.rules.guide3': 'Sé honesto sobre lo que hace y cuesta FruitCrew. No prometas descuentos ni funciones.',
