  'ambPublic.lead': 'Presenta FruitCrew a cafés, tiendas y restaurantes cerca de ti. Trabaja cuando te convenga, según tus clases.',
  'ambPublic.whatTitle': '¿Qué es FruitCrew?',
  'ambPublic.what': 'Horarios para equipos pequeños: el encargado arma la semana en minutos, los trabajadores ven y cambian sus turnos en el móvil y las horas de nómina se suman solas.',
  'ambPublic.howTitle': 'Cómo funciona',
