  'help.subtitle': 'Una guía breve para dueños y gerentes.',
  'help.setup.summary': 'Seis pasos hasta tu primer horario',
  'help.week.summary': 'Qué pasa cada semana y cuándo',
  'help.edit.summary': 'Añadir, mover y ofrecer turnos',
  'help.requests.summary': 'Cambios, turnos tomados y días libres',
  'help.team.summary': 'Perfiles, niveles y registros',
  'help.payroll.summary': 'Horas, horas extra, pago y exportar',
  'help.clock.summary': 'Fichaje, hojas de horas y horas del POS',
