  'help.chat.summary': 'Mensajes y notas de relevo',
  'help.open': 'Abrir {page} ›',
  'help.contact': '¿Sigues con dudas? Con gusto te ayudamos:',
  'help.week.title': 'Tu rutina semanal',
  'help.week.1': 'Viernes — todos reciben un recordatorio para revisar su disponibilidad de la próxima semana.',
  'help.week.2': 'Sábado — FruitCrew prepara un borrador de la próxima semana con la disponibilidad de todos y tus necesidades de turno. Inicio te avisa cuando está listo.',
  'help.week.3': 'Tú — abre Horario, revisa el borrador, corrige lo que haga falta y toca Publicar horario. Tu equipo recibe un aviso. Esta semana sigue en curso hasta que termine el domingo: ‹ te lleva de vuelta para cambiarla, y el equipo aún puede intercambiar turnos.',
  'help.week.4': 'Cambia estos días y horas para cada tienda en Ajustes › Recordatorios y borrador automático.',
  'help.edit.title': 'Cambiar el horario',
  'help.edit.1': 'Toca a cualquiera en el tablero para cambiar sus turnos, o + Agregar turno para poner a quien sea en cualquier día. Días muestra la semana día por día; Personas, una fila por persona con sus horas. Si falta gente algún día, arriba verás cuántas personas faltan.',
  'help.edit.2': '¿Cambiaste una semana ya publicada? Toca Volver a publicar horario para que tu equipo vea el cambio.',
  'help.edit.3': 'Usa ‹ y › para moverte entre semanas. Planear la próxima semana empieza la siguiente mientras esta sigue publicada.',
  'help.edit.4': '¿Falta gente o alguien no puede ir? Toca el hueco (o su turno) y elige Ofrecerlo al equipo: aparece en la Bolsa de todos para que lo tome quien esté libre. En ⋯ también tienes Copiar la semana pasada y Publicar sin avisar a nadie.',
  'help.requests.title': 'Solicitudes',
  'help.requests.1': 'Los trabajadores ceden, intercambian y toman turnos en la Bolsa. Todo lo que necesita tu visto bueno llega a Solicitudes: apruébalo o recházalo ahí.',
  'help.requests.2': 'El tiempo libre también aparece ahí. El programador ya evita esos días; Entendido les avisa que lo viste, y Rechazar les dice (con tu motivo) que aún pueden programarlos.',
  'help.team.title': 'Tu equipo',
  'help.team.1': 'Toca a cualquiera en Equipo para ver todo sobre esa persona: tiendas y nivel, límite de horas, reglas de días, turnos fijos, disponibilidad, tiempo libre y horas trabajadas.',
  'help.team.2': 'Los niveles son Nuevo, Regular, Sénior y Gerente. A los nuevos solo se les asignan franjas que piden una persona Nueva, así nunca trabajan solos.',
  'help.team.3': 'Quienes se unen con el enlace de registro de tu tienda esperan en Equipo hasta que los apruebes.',
  'help.payroll.title': 'Nómina',
  'help.payroll.1': 'Nómina suma las horas de todos en un periodo de pago o en las fechas que elijas, con las horas extra (más de 40 en una semana) aparte y el pago estimado cuando pones sueldos en Equipo; Exportar CSV te lo da para tu servicio de nómina. Elige semanal, quincenal o mensual en Ajustes › Empresa.',
  'help.clock.title': 'Reloj de fichaje',
  'help.clock.1': 'Está apagado hasta que lo actives, por tienda, en Ajustes › Reloj de fichaje. Con FruitCrew, cada uno ficha entrada, salida y descansos desde Mis turnos, e Inicio muestra quién está y quién no. Con tu POS (Toast, Square…), importas sus registros.',
  'help.clock.2': 'Las hojas de horas (en Nómina) ponen las horas de cada día junto al horario y marcan llegadas tarde, salidas sin fichar y horas fuera del horario. Corrige o añade un registro y aprueba la semana; Nómina usa las horas trabajadas de esa tienda.',
  'help.settings.title': 'Ajustes',
  'help.settings.1': 'Empresa — el nombre de tu negocio, el ciclo de pago y si los gerentes pueden ver los sueldos.',
  'help.settings.2': 'Ubicaciones — las necesidades de turno de cada tienda, horarios y feriados, responsabilidades, enlace de registro y horarios de recordatorio.',
  'help.settings.3': 'Gerentes y dueños — invita a otros a ayudarte con el horario.',
  'help.chat.title': 'Chat y Notas',
  'help.chat.1': 'El chat es para mensajes de la tienda y directos. Las Notas son el relevo del turno — reembolsos, quejas, objetos perdidos — y siguen abiertas hasta que alguien las resuelve.',
